import React, { useEffect, useState } from "react";
import PropTypes from "prop-types";
import Accordion from "../tools/finder__accordion";
import type { Radio } from "../../types/filters/filters";

function Finder__Radio(props: Radio) {
  const filterValues = props.facet.filterValues ?? true;
  const rawCurrentValue = props.query.facets?.[props.facet.meta];
  const currentValue = Array.isArray(rawCurrentValue)
    ? rawCurrentValue[0] ?? ""
    : String(rawCurrentValue ?? "");
  const initialChecked = currentValue ? 1 : 0;
  const [checkTotal, setCheckTotal] = useState(initialChecked);

  useEffect(() => {
    setCheckTotal(initialChecked);
  }, [initialChecked]);

  const responseValues = props.responseFacet[0]?.allValues ?? [];
  const responseValueNames = responseValues.map((value) =>
    value.data.toLowerCase(),
  );

  const setFacet = (value: string) => {
    const newQuery = {
      ...props.query,
      facets: { ...props.query.facets },
    };

    props.dependencies?.forEach((facet) => {
      delete newQuery.facets[facet.meta];
    });

    if (value) newQuery.facets[props.facet.meta] = value;
    else delete newQuery.facets[props.facet.meta];

    newQuery.startRank = 1;
    newQuery.misspelling = null;
    newQuery.interacted = true;

    props.update.query(newQuery);
    props.update.results(!props.update.updateState);
  };

  const radios = props.facet.values?.map((value, index) => {
    const normalizedValue = value.data.toLowerCase();
    const responseValue = responseValues.find(
      (candidate) => candidate.data.toLowerCase() === normalizedValue,
    );
    const available = responseValueNames.includes(normalizedValue);

    if (filterValues && !available && currentValue.toLowerCase() !== normalizedValue) {
      return null;
    }

    const id = `meta_${props.facet.meta}_sand--${props.mobile ? "mobile" : "desktop"}--${index}`;
    const count = responseValue?.count;

    return (
      <div className="v26-finder__radio__option" key={value.data}>
        <input
          type="radio"
          id={id}
          name={`meta_${props.facet.meta}_sand`}
          value={normalizedValue}
          checked={currentValue.toLowerCase() === normalizedValue}
          onChange={() => setFacet(normalizedValue)}
        />
        <label className="v26-finder_filters__label" htmlFor={id}>
          {value.label}
          {count !== undefined && count > 0 ? ` (${count})` : ""}
        </label>
      </div>
    );
  });

  const content = (
    <fieldset className="v26-finder__filter v26-finder__radio">
      <legend className="sr-only">{props.facet.name}</legend>
      <div className="v26-finder__radio__option">
        <input
          type="radio"
          id={`meta_${props.facet.meta}_sand--${props.mobile ? "mobile" : "desktop"}--all`}
          name={`meta_${props.facet.meta}_sand`}
          value=""
          checked={currentValue === ""}
          onChange={() => setFacet("")}
        />
        <label className="v26-finder_filters__label" htmlFor={`meta_${props.facet.meta}_sand--${props.mobile ? "mobile" : "desktop"}--all`}>
          {props.facet.noSelection}
        </label>
      </div>
      {radios}
    </fieldset>
  );

  return props.facet.accordion && !props.matrixState ? (
    <Accordion title={props.facet.name} matrixState={false} totalChecked={checkTotal}>
      {content}
    </Accordion>
  ) : (
    content
  );
}

Finder__Radio.propTypes = {
  facet: PropTypes.object.isRequired,
  query: PropTypes.object.isRequired,
  responseFacet: PropTypes.arrayOf(PropTypes.object).isRequired,
  update: PropTypes.object.isRequired,
  dependencies: PropTypes.arrayOf(PropTypes.object),
  mobile: PropTypes.bool,
};

export default Finder__Radio;
