import React from "react";
import PropTypes from "prop-types";
import ClearFilterTag from "../filters/finder__clearFilterTag";
import Reset from "../filters/finder__reset";
import type { ClearFilters } from "../../types/results/results";
import { flattenFacetDetails } from "../../types/facet";

function Finder__Clear__Filters(props: ClearFilters) {
  const { query, clear, update, config, updating } = props;
  const facetsValues = query.facets ? Object.values(query.facets) : [];
  const hasNoEmptyFacet = facetsValues.some(
  v => !(v === '' || (Array.isArray(v) && v.length === 0)));
  
  const clearFiltersDesktop =
    !updating && hasNoEmptyFacet ? (
      <div className="v26-finder__filters__reset v26-finder__filters__reset--desktop">
        <Reset
          clear={props.clear}
          resetSort={false}
          matrixState={props.matrixState}
          site={props.config.site || "city"}
        />
      </div>
    ) : null;
  const facetLabels = flattenFacetDetails(config.facetLabels || []);

  return (
    <div className="v26-finder__results__clear-filters">
      {facetLabels.map((facet, index) => {
        if (query.facets && query.facets[facet.meta]) {
          const dependencies = [
            ...facetLabels.filter(
              (candidate) => candidate.dependency === facet.meta,
            ),
            ...(facet.type === "drillDown"
              ? facetLabels
                  .slice(index + 1)
                  .filter(
                    (candidate) =>
                      candidate.type === "drillDown" &&
                      candidate.facetName === facet.facetName,
                  )
              : []),
          ];

          if (Array.isArray(query.facets[facet.meta])) {
            return (query.facets[facet.meta] as string[]).map(
              (facetValue: string) => (
                <ClearFilterTag
                  key={`${facet.meta}-${facetValue}`}
                  value={facetValue}
                  facet={facet}
                  query={query}
                  update={update}
                  clear={clear}
                  dependencies={dependencies}
                  site={props.config.site || "city"}
                  matrixState={props.matrixState}
                  config={props.config}
                />
              ),
            );
          }

          return (
            <ClearFilterTag
              key={`${facet.meta}-${query.facets[facet.meta] as string}`}
              value={query.facets[facet.meta] as string}
              facet={facet}
              query={query}
              update={update}
              clear={clear}
              dependencies={dependencies}
              site={props.config.site || "city"}
              matrixState={props.matrixState}
              config={props.config}
            />
          );
        }

        return null;
      })}
      {clearFiltersDesktop}
    </div>
  );
}

Finder__Clear__Filters.propTypes = {
  query: PropTypes.object,
  update: PropTypes.object,
  clear: PropTypes.func,
  config: PropTypes.object,
  matrixState: PropTypes.bool,
  updating: PropTypes.bool,
};

export default Finder__Clear__Filters;
