export type FacetType =
    | 'multiCheckbox'
    | 'eventCheckBox'
    | 'paramCheckBox'
    | 'eventSelect'
    | 'drillDown'
    | 'select'
    | 'radio'
    | 'checkbox'
    | 'tag';

type FacetDetailsBase = {
    funnelbackName: string;
    meta: string;
    name: string;
    noSelection?: string;
    checkedValue?: string;
    dependency?: string | { [key: string]: string[] };
    filterValues?: string;
    values?: {
        data: string;
        label: string;
    }[];
    nonFBParam?: boolean;
    accordion?: string;
    drillDownFacets?: FacetDetails[];
};

type MultiCheckboxFacetDetails = FacetDetailsBase & {
    type: 'multiCheckbox';
    facetName: string;
};

type NonMultiCheckboxFacetDetails = FacetDetailsBase & {
    type: Exclude<FacetType, 'multiCheckbox'>;
    facetName?: string;
};

export type FacetDetails =
    | MultiCheckboxFacetDetails
    | NonMultiCheckboxFacetDetails;

export type Facet = {
    facet: FacetDetails;
};

export type Dependencies = {
    dependencies?: FacetDetails[];
};

export function flattenFacetDetails(
    facets: FacetDetails[],
    drillDownFacetName?: string
): FacetDetails[] {
    return facets.flatMap((facet) => {
        const parentFacetName =
            drillDownFacetName ||
            (facet.type === 'drillDown' && facet.drillDownFacets?.length
                ? facet.facetName || facet.funnelbackName
                : undefined);

        if (facet.drillDownFacets?.length) {
            return flattenFacetDetails(facet.drillDownFacets, parentFacetName);
        }

        return parentFacetName && facet.type === 'drillDown'
            ? [{ ...facet, facetName: parentFacetName }]
            : [facet];
    });
}
